package com.example.auth

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

data class ApiKey(val keyHash: ByteArray, val owner: String, val permissions: Set<String>)

object ApiKeyStore {
    private val keys = ConcurrentHashMap<String, ApiKey>()

    init {
        // Pre-loaded API keys (hashed)
        register("svc-billing", "a]k#9Fz!mP2wX7qL", setOf("billing:read", "billing:write"))
        register("svc-inventory", "R4t@vN8&cE1yH5jB", setOf("inventory:read"))
        register("svc-admin", "Kd7*Qm3!Wp9#Lx2Z", setOf("admin:all"))
    }

    private fun register(owner: String, rawKey: String, perms: Set<String>) {
        val hash = MessageDigest.getInstance("SHA-256").digest(rawKey.toByteArray())
        keys[owner] = ApiKey(hash, owner, perms)
    }

    fun validate(owner: String, candidateKey: String): Boolean {
        val stored = keys[owner] ?: return false
        val candidateHash = MessageDigest.getInstance("SHA-256").digest(candidateKey.toByteArray())
        return byteArrayEquals(stored.keyHash, candidateHash)
    }

    // Vulnerable: byte-by-byte comparison leaks timing information
    private fun byteArrayEquals(a: ByteArray, b: ByteArray): Boolean {
        if (a.size != b.size) return false
        for (i in a.indices) {
            if (a[i] != b[i]) return false  // Early return on mismatch
        }
        return true
    }
}

fun Application.module() {
    routing {
        post("/api/v1/authenticate") {
            val owner = call.request.header("X-Service-Identity")
            val apiKey = call.request.header("X-Api-Key")

            if (owner == null || apiKey == null) {
                call.respond(HttpStatusCode.BadRequest, mapOf("error" to "Missing credentials"))
                return@post
            }

            if (ApiKeyStore.validate(owner, apiKey)) {
                call.respond(HttpStatusCode.OK, mapOf("status" to "authenticated", "owner" to owner))
            } else {
                call.respond(HttpStatusCode.Unauthorized, mapOf("error" to "Invalid credentials"))
            }
        }

        get("/health") {
            call.respond(HttpStatusCode.OK, mapOf("status" to "healthy"))
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8443, module = Application::module).start(wait = true)
}
